query:
query {
    nodes(ids: ["gid://shopify/Product/10361643401492","gid://shopify/Product/10361644220692"]) {
        ... on Product {
            id
            title
            descriptionHtml
            tags
            status
            productType
            vendor
            templateSuffix
            publishedAt
            createdAt
            status
            handle
            seo { title description }
            media(first: 1) { nodes { preview { image { url } } } }
            publications(first: 10) { nodes { channel { name } } }
            category: metafield(namespace: "custom", key: "category") { value }
            z8_offers: metafield(namespace: "custom", key: "z8_offers") { value }
            testing: metafield(namespace: "custom", key: "testing") { value }
            productCategory { productTaxonomyNode { fullName } }
            variants(first: 50) {
                nodes {
                    id
                    title
                    price
                    compareAtPrice
                    sku
                    barcode
                    inventoryQuantity
                    taxable
                    inventoryPolicy
                    unitPriceMeasurement {
                        measuredType
                        quantityValue
                        quantityUnit
                        referenceValue
                        referenceUnit
                    }
                    testing: metafield(namespace: "custom", key: "testing") { value }
                    inventoryItem {
                        tracked
                        unitCost { amount }
                        measurement { weight { value unit } }
                        harmonizedSystemCode
                        countryCodeOfOrigin
                    }
                }
            }
        }
    }
}
